package com.portfolio.assetory.refund;
import org.springframework.http.*;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.*;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import com.portfolio.assetory.global.auth.CurrentUserId;import com.portfolio.assetory.global.exception.*;import com.portfolio.assetory.global.response.ApiResponse;import com.portfolio.assetory.order.domain.*;import com.portfolio.assetory.order.repository.OrderItemRepository;import com.portfolio.assetory.access.repository.ProductAccessRepository;
@RestController @RequestMapping("/api/refunds") public class RefundController{private final RefundService s;public RefundController(RefundService s){this.s=s;}@PostMapping public ResponseEntity<ApiResponse<Response>> request(@CurrentUserId Long u,@Valid @RequestBody Request r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(s.request(u,r)));}@PatchMapping("/{id}/cancel")public ResponseEntity<ApiResponse<Response>> cancel(@CurrentUserId Long u,@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success(s.cancel(u,id)));}public record Request(@NotNull Long orderItemId,@NotBlank @Size(min=10,max=1000)String reason){}public record Response(Long refundId,Long orderItemId,Long productId,String productName,java.math.BigDecimal refundAmount,String reason,String status,java.time.LocalDateTime requestedAt,java.time.LocalDateTime canceledAt){static Response from(Refund r){var i=r.getOrderItem();return new Response(r.getId(),i.getId(),i.getProduct().getId(),i.getProductName(),r.getRefundAmount(),r.getReason(),r.getStatus().name(),r.getRequestedAt(),r.getCanceledAt());}}}
@Service @Transactional class RefundService{private final OrderItemRepository items;private final RefundRepository refunds;RefundService(OrderItemRepository i,RefundRepository r){items=i;refunds=r;}RefundController.Response request(Long u,RefundController.Request r){var i=items.findById(r.orderItemId()).orElseThrow(()->new BusinessException(ErrorCode.ORDER_NOT_FOUND));if(!i.getOrder().getBuyer().getId().equals(u))throw new BusinessException(ErrorCode.FORBIDDEN);if(refunds.existsByOrderItemId(i.getId()))throw new BusinessException(ErrorCode.REFUND_ALREADY_EXISTS);if(i.getOrder().getStatus()!=OrderStatus.PAID)throw new BusinessException(ErrorCode.INVALID_REFUND_STATUS);i.getOrder().markRefundRequested();return RefundController.Response.from(refunds.save(Refund.request(i,r.reason())));}RefundController.Response cancel(Long u,Long id){var r=refunds.findForBuyer(id,u).orElseThrow(()->new BusinessException(ErrorCode.REFUND_NOT_FOUND));if(r.getStatus()!=RefundStatus.REQUESTED)throw new BusinessException(ErrorCode.INVALID_REFUND_STATUS);r.cancel();r.getOrderItem().getOrder().restorePaid();return RefundController.Response.from(r);}}
